-- AI-generated by OpenAI Codex.
--
-- Remember Chinese/English and full/half width across sessions and restarts.
-- In librime 1.17.0, Shift/ascii_composer and key_binder's toggle change session
-- state without saving it through switcher/save_options. This helper listens
-- for those changes, saves the two options to user.yaml, and restores them on init.
-- Upstream issue: https://github.com/rime/librime/issues/1013
-- API: https://github.com/hchunhui/librime-lua/blob/master/src/types.cc
local remember_options = {}

function remember_options.init(env)
    -- Keep the switcher alive while using its user_config pointer.
    env.switcher = Switcher(env.engine)
    local user_config = env.switcher.user_config
    local user_path = rime_api.get_user_data_dir() .. "/user.yaml"
    local config = env.engine.schema.config
    local context = env.engine.context
    local watched = { ascii_mode = true, full_shape = true }

    for index = 0, (config:get_list_size("switches") or 0) - 1 do
        local path = "switches/@" .. index
        local name = config:get_string(path .. "/name")
        if name and watched[name] then
            local saved = user_config:get_bool("var/option/" .. name)
            if saved ~= nil then
                -- Native resets run after init. Let saved preferences win.
                -- Schema config changes here stay in memory.
                assert(config:set_int(path .. "/reset", -1))
                context:set_option(name, saved)
            end
        end
    end

    env.connection = context.option_update_notifier:connect(function(ctx, name)
        if not watched[name] then
            return
        end
        local path = "var/option/" .. name
        local value = ctx:get_option(name)
        if user_config:get_bool(path) ~= value then
            assert(user_config:set_bool(path, value))
            assert(user_config:save_to_file(user_path), "Could not save Rime switch preferences")
        end
    end)
end

function remember_options.fini(env)
    env.connection:disconnect()
    env.connection = nil
    env.switcher = nil
end

function remember_options.func()
    return 2 -- kNoop: leave key handling to the existing processors.
end

return remember_options
